source='''from math import gcd

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    positions = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != bg:
                positions.setdefault(v, []).append((r, c))
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg}
    for color, pts in positions.items():
        if len(pts) < 2:
            continue
        pts.sort()
        (r0, c0), (r1, c1) = pts[0], pts[-1]
        dr, dc = r1-r0, c1-c0
        g = gcd(abs(dr), abs(dc))
        dr, dc = dr//g, dc//g
        # Extend outwards from both ends, stopping at the first existing mark.
        for r, c, sr, sc in ((r0, c0, -dr, -dc), (r1, c1, dr, dc)):
            rr, cc = r+sr, c+sc
            while 0 <= rr < h and 0 <= cc < w:
                if (rr, cc) in occupied:
                    break
                out[rr][cc] = color
                rr += sr
                cc += sc
    return out
'''
